<?php
require 'config.php';
require_auth();
$pdo=db();
$page=$_GET['page']??'dashboard';
$allowed=['dashboard','teachers','schedules','finance','reports','users','settings'];
if(!in_array($page,$allowed,true))$page='dashboard';
$today=date('Y-m-d');
$currency=$pdo->query('SELECT currency FROM settings WHERE id=1')->fetchColumn() ?: 'د.ع';

if($_SERVER['REQUEST_METHOD']==='POST'){
    check_csrf(); $action=$_POST['action']??'';
    try{
        if($action==='teacher_save'){
            $id=(int)($_POST['id']??0);$data=[trim($_POST['name']??''),trim($_POST['subject']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),(float)($_POST['fee']??0),trim($_POST['notes']??''),(int)($_POST['active']??1)];
            if($id){$st=$pdo->prepare('UPDATE teachers SET name=?,subject=?,phone=?,whatsapp=?,fee=?,notes=?,active=? WHERE id=?');$data[]=$id;$st->execute($data);flash('تم تعديل بيانات الأستاذ');}
            else{$pdo->prepare('INSERT INTO teachers(name,subject,phone,whatsapp,fee,notes,active) VALUES(?,?,?,?,?,?,?)')->execute($data);flash('تمت إضافة الأستاذ بنجاح');}
            redirect('index.php?page=teachers');
        }
        if($action==='teacher_delete'){require_admin();$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM teachers WHERE id=?')->execute([$id]);flash('تم حذف الأستاذ');redirect('index.php?page=teachers');}
        if($action==='schedule_save'){
            $id=(int)($_POST['id']??0);$teacher=(int)$_POST['teacher_id'];$title=trim($_POST['title']??'');$start=str_replace('T',' ',trim($_POST['start_at']??''));$end=trim($_POST['end_at']??'');$end=$end?str_replace('T',' ',$end):null;$status=$_POST['status']??'scheduled';$notes=trim($_POST['notes']??'');
            if($id){$pdo->prepare('UPDATE schedules SET teacher_id=?,title=?,start_at=?,end_at=?,status=?,notes=? WHERE id=?')->execute([$teacher,$title,$start,$end,$status,$notes,$id]);flash('تم تعديل الموعد');}
            else{$pdo->prepare('INSERT INTO schedules(teacher_id,title,start_at,end_at,status,notes) VALUES(?,?,?,?,?,?)')->execute([$teacher,$title,$start,$end,$status,$notes]);flash('تمت إضافة الموعد');}
            redirect('index.php?page=schedules&view='.urlencode($_POST['view']??'week'));
        }
        if($action==='schedule_delete'){require_admin();$pdo->prepare('DELETE FROM schedules WHERE id=?')->execute([(int)$_POST['id']]);flash('تم حذف الموعد');redirect('index.php?page=schedules');}
        if($action==='schedule_status'){$pdo->prepare('UPDATE schedules SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('تم تحديث حالة الموعد');redirect('index.php?page=schedules');}
        if($action==='transaction_save'){
            $id=(int)($_POST['id']??0);$type=$_POST['type']??'income';$teacher=($_POST['teacher_id']??'')!==''?(int)$_POST['teacher_id']:null;$amount=max(0,(float)$_POST['amount']);$desc=trim($_POST['description']??'');$date=$_POST['transaction_date']??$today;
            if($type==='teacher_payment' && !$teacher) throw new Exception('دفعة الأستاذ يجب أن ترتبط بأستاذ.');
            if($id){$pdo->prepare('UPDATE transactions SET type=?,teacher_id=?,amount=?,description=?,transaction_date=? WHERE id=?')->execute([$type,$teacher,$amount,$desc,$date,$id]);flash('تم تعديل العملية المالية');}
            else{$pdo->prepare('INSERT INTO transactions(type,teacher_id,amount,description,transaction_date) VALUES(?,?,?,?,?)')->execute([$type,$teacher,$amount,$desc,$date]);flash('تم تسجيل العملية المالية');}
            redirect('index.php?page=finance');
        }
        if($action==='transaction_delete'){require_admin();$pdo->prepare('DELETE FROM transactions WHERE id=?')->execute([(int)$_POST['id']]);flash('تم حذف العملية');redirect('index.php?page=finance');}
        if($action==='user_save'){require_admin();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'staff';$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('أدخل اسم وبريد صحيحين.');if($id){if($pass){$pdo->prepare('UPDATE users SET name=?,email=?,role=?,password_hash=? WHERE id=?')->execute([$name,$email,$role,password_hash($pass,PASSWORD_DEFAULT),$id]);}else{$pdo->prepare('UPDATE users SET name=?,email=?,role=? WHERE id=?')->execute([$name,$email,$role,$id]);}flash('تم تعديل المستخدم');}else{$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)')->execute([$name,$email,password_hash($pass?:'Admin@123',PASSWORD_DEFAULT),$role]);flash('تمت إضافة المستخدم');}redirect('index.php?page=users');}
        if($action==='user_delete'){require_admin();$id=(int)$_POST['id'];if($id===$_SESSION['user']['id'])throw new Exception('لا يمكنك حذف حسابك الحالي.');$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);flash('تم حذف المستخدم');redirect('index.php?page=users');}
        if($action==='settings'){require_admin();$pdo->prepare('UPDATE settings SET studio_name=?,backup_email=?,studio_whatsapp=?,currency=? WHERE id=1')->execute([trim($_POST['studio_name']),trim($_POST['backup_email']),trim($_POST['studio_whatsapp']),trim($_POST['currency'])?:'د.ع']);flash('تم حفظ الإعدادات');redirect('index.php?page=settings');}
        if($action==='backup'){require_admin();$sql=sql_backup($pdo);$name='academic-studio-backup-'.date('Y-m-d-His').'.sql';header('Content-Type:application/sql; charset=utf-8');header('Content-Disposition:attachment; filename="'.$name.'"');echo $sql;exit;}
    }catch(Throwable $e){flash($e->getMessage(),'bad');redirect('index.php?page='.$page);}
}

$setting=$pdo->query('SELECT * FROM settings WHERE id=1')->fetch();
$teachers=$pdo->query('SELECT * FROM teachers ORDER BY active DESC,name')->fetchAll();
$stats=[
 'teachers'=>(int)$pdo->query('SELECT COUNT(*) FROM teachers WHERE active=1')->fetchColumn(),
 'schedules'=>(int)$pdo->query("SELECT COUNT(*) FROM schedules WHERE start_at>=NOW() AND status='scheduled'")->fetchColumn(),
 'income'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE type='income'")->fetchColumn(),
 'expense'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE type='expense'")->fetchColumn(),
 'teacher_payments'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE type='teacher_payment'")->fetchColumn()
];
$upcoming=$pdo->query("SELECT s.*,t.name teacher,t.whatsapp FROM schedules s JOIN teachers t ON t.id=s.teacher_id WHERE s.start_at>=NOW() AND s.status='scheduled' ORDER BY s.start_at LIMIT 10")->fetchAll();
$tx=$pdo->query("SELECT x.*,t.name teacher FROM transactions x LEFT JOIN teachers t ON t.id=x.teacher_id ORDER BY x.transaction_date DESC,x.id DESC LIMIT 15")->fetchAll();
$flash=take_flash();
$view=$_GET['view']??'week';
$anchor=isset($_GET['date'])&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['date'])?$_GET['date']:$today;
function day_name_ar($date){$n=(int)date('N',strtotime($date));return ['الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت','الأحد'][$n-1];}
$weekStart=date('Y-m-d',strtotime($anchor.' -'.((int)date('N',strtotime($anchor))-1).' days'));
$weekDays=[];for($i=0;$i<7;$i++)$weekDays[]=date('Y-m-d',strtotime($weekStart." +{$i} days"));
$monthStart=date('Y-m-01',strtotime($anchor));$monthEnd=date('Y-m-t',strtotime($anchor));
$monthRows=$pdo->prepare("SELECT s.*,t.name teacher,t.whatsapp FROM schedules s JOIN teachers t ON t.id=s.teacher_id WHERE DATE(s.start_at) BETWEEN ? AND ? ORDER BY s.start_at");$monthRows->execute([$monthStart,$monthEnd]);$monthEvents=$monthRows->fetchAll();
$weekRows=$pdo->prepare("SELECT s.*,t.name teacher,t.whatsapp FROM schedules s JOIN teachers t ON t.id=s.teacher_id WHERE DATE(s.start_at) BETWEEN ? AND ? ORDER BY s.start_at");$weekRows->execute([$weekStart,$weekDays[6]]);$weekEvents=$weekRows->fetchAll();
$editTeacher=null;if($page==='teachers'&&isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM teachers WHERE id=?');$st->execute([(int)$_GET['edit']]);$editTeacher=$st->fetch();}
$editSchedule=null;if($page==='schedules'&&isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM schedules WHERE id=?');$st->execute([(int)$_GET['edit']]);$editSchedule=$st->fetch();}
$editTx=null;if($page==='finance'&&isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM transactions WHERE id=?');$st->execute([(int)$_GET['edit']]);$editTx=$st->fetch();}
$users=$page==='users'?$pdo->query('SELECT id,name,email,role,created_at FROM users ORDER BY id')->fetchAll():[];
$editUser=null;if($page==='users'&&isset($_GET['edit'])){$st=$pdo->prepare('SELECT id,name,email,role FROM users WHERE id=?');$st->execute([(int)$_GET['edit']]);$editUser=$st->fetch();}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102f3b"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><meta name="apple-mobile-web-app-title" content="أكاديمي"><link rel="apple-touch-icon" href="assets/icons/icon-192.png"><link rel="manifest" href="assets/manifest.json"><link rel="stylesheet" href="assets/style.css"><title><?=e($setting['studio_name'])?></title></head><body>
