<main><header><div><h2><?=e(['dashboard'=>'لوحة التحكم','teachers'=>'إدارة الأساتذة','schedules'=>'الجدول الأسبوعي والشهري','finance'=>'الحسابات والمالية','reports'=>'التقارير','users'=>'المستخدمون والصلاحيات','settings'=>'الإعدادات'][$page])?></h2><small>استوديو أكاديمي · <?=date('Y/m/d')?></small></div><div class="date"><?=day_name_ar($today)?></div></header>
<?php if($flash):?><div class="alert <?=$flash[1]==='bad'?'bad':''?>"><?=e($flash[0])?></div><?php endif;?>
<?php if($page==='dashboard'):?>
<section class="cards"><div class="stat"><span>الأساتذة النشطون</span><b><?=$stats['teachers']?></b></div><div class="stat"><span>المواعيد القادمة</span><b><?=$stats['schedules']?></b></div><div class="stat"><span>الواردات</span><b><?=money($stats['income'],$currency)?></b></div><div class="stat"><span>صافي بعد المصروف والدفعات</span><b><?=money($stats['income']-$stats['expense']-$stats['teacher_payments'],$currency)?></b></div></section>
<div class="grid2"><section class="panel"><div class="panel-head"><h3>المواعيد القادمة</h3><a href="?page=schedules">عرض الجدول</a></div><?php if(!$upcoming):?><div class="empty">لا توجد مواعيد قادمة.</div><?php else:?><table><tr><th>الأستاذ</th><th>الموعد</th><th>العنوان</th><th>تذكير</th></tr><?php foreach($upcoming as $r):$msg='تذكير من استوديو أكاديمي: موعدك '.$r['title'].' بتاريخ '.date('Y-m-d H:i',strtotime($r['start_at']));?><tr><td><?=e($r['teacher'])?></td><td class="nowrap"><?=e(date('Y-m-d H:i',strtotime($r['start_at'])))?></td><td><?=e($r['title'])?></td><td><?php if($r['whatsapp']):?><a target="_blank" href="<?=e(wa_link($r['whatsapp'],$msg))?>">واتساب</a><?php else:?><span class="hint">لا يوجد رقم</span><?php endif;?></td></tr><?php endforeach;?></table><?php endif;?></section>
<section class="panel"><div class="panel-head"><h3>ملخص مالي</h3><a href="?page=finance">فتح المالية</a></div><div class="report-grid"><div><span class="hint">الوارد</span><div class="profit"><?=money($stats['income'],$currency)?></div></div><div><span class="hint">المصروف</span><div class="profit"><?=money($stats['expense'],$currency)?></div></div><div><span class="hint">دفعات الأساتذة</span><div class="profit"><?=money($stats['teacher_payments'],$currency)?></div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><p class="hint">دفعات الأساتذة مستقلة عن الوارد والمصروف ولا تدخل في قسم الواردات.</p></section></div>
