<dialog id="scheduleModal" class="modal" <?=($editSchedule?'open':'')?>><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="schedule_save"><input type="hidden" name="id" value="<?=e($editSchedule['id']??0)?>"><input type="hidden" name="view" value="<?=e($view)?>"><h3><?= $editSchedule?'تعديل الموعد':'إضافة موعد جديد'?></h3><div class="form-grid"><div class="field"><label>الأستاذ</label><select name="teacher_id" required><option value="">اختر الأستاذ</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>" <?=($editSchedule['teacher_id']??0)==$t['id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="field"><label>العنوان</label><input name="title" required value="<?=e($editSchedule['title']??'محاضرة')?>"></div><div class="field"><label>البداية</label><input type="datetime-local" name="start_at" required value="<?=isset($editSchedule['start_at'])?date('Y-m-d\TH:i',strtotime($editSchedule['start_at'])):''?>"></div><div class="field"><label>النهاية</label><input type="datetime-local" name="end_at" value="<?=isset($editSchedule['end_at'])&&$editSchedule['end_at']?date('Y-m-d\TH:i',strtotime($editSchedule['end_at'])):''?>"></div><div class="field"><label>الحالة</label><select name="status"><option value="scheduled" <?=($editSchedule['status']??'scheduled')==='scheduled'?'selected':''?>>مجدول</option><option value="done" <?=($editSchedule['status']??'')==='done'?'selected':''?>>منجز</option><option value="cancelled" <?=($editSchedule['status']??'')==='cancelled'?'selected':''?>>ملغي</option></select></div><div class="field full"><label>ملاحظات</label><textarea name="notes"><?=e($editSchedule['notes']??'')?></textarea></div></div><div class="actions"><button class="primary">حفظ</button><?php if($editSchedule&&is_admin()):?><button type="submit" name="action" value="schedule_delete" formaction="index.php" class="danger" onclick="return confirm('حذف الموعد؟')">